/// Defining path of one name the Rust standard prelude brings into every module.
pub(in crate::static_resolution) fn rust_prelude(name: &str) -> Option<&'static str> {
    Some(match name {
        "AsMut" => "core::convert::AsMut",
        "AsRef" => "core::convert::AsRef",
        "Box" => "alloc::boxed::Box",
        "Clone" => "core::clone::Clone",
        "Copy" => "core::marker::Copy",
        "Default" => "core::default::Default",
        "DoubleEndedIterator" => "core::iter::DoubleEndedIterator",
        "Drop" => "core::ops::Drop",
        "Eq" => "core::cmp::Eq",
        "Err" => "core::result::Result::Err",
        "ExactSizeIterator" => "core::iter::ExactSizeIterator",
        "Extend" => "core::iter::Extend",
        "Fn" => "core::ops::Fn",
        "FnMut" => "core::ops::FnMut",
        "FnOnce" => "core::ops::FnOnce",
        "From" => "core::convert::From",
        "FromIterator" => "core::iter::FromIterator",
        "Into" => "core::convert::Into",
        "IntoIterator" => "core::iter::IntoIterator",
        "Iterator" => "core::iter::Iterator",
        "None" => "core::option::Option::None",
        "Ok" => "core::result::Result::Ok",
        "Option" => "core::option::Option",
        "Ord" => "core::cmp::Ord",
        "PartialEq" => "core::cmp::PartialEq",
        "PartialOrd" => "core::cmp::PartialOrd",
        "Result" => "core::result::Result",
        "Send" => "core::marker::Send",
        "Sized" => "core::marker::Sized",
        "Some" => "core::option::Option::Some",
        "String" => "alloc::string::String",
        "Sync" => "core::marker::Sync",
        "ToOwned" => "alloc::borrow::ToOwned",
        "ToString" => "alloc::string::ToString",
        "TryFrom" => "core::convert::TryFrom",
        "TryInto" => "core::convert::TryInto",
        "Unpin" => "core::marker::Unpin",
        "Vec" => "alloc::vec::Vec",
        "drop" => "core::mem::drop",
        _ => return None,
    })
}

#[cfg(test)]
mod tests {
    #[test]
    fn name_tables_are_ordered_for_binary_search() {
        assert!(super::PYTHON_STANDARD_MODULES.is_sorted());
        assert!(super::PYTHON_BUILTINS.is_sorted());
        assert!(super::NODE_BUILTIN_MODULES.is_sorted());
    }
}
